from collections import defaultdict

def cluster_states(grid_world):
    # Define the grid and goal
    grid = grid_world['grid']
    goal = grid_world['goal']
    start = grid_world['start']

    # Get the coordinates of each cell in the grid
    cells = {}
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell != 'X':
                cells[cell] = (i, j)

    # Define the possible actions and their effects
    actions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    # Perform value iteration to get the optimal values and policies
    values = {cell: float('-inf') for cell in cells}
    values[goal] = 0
    policy = {}
    for _ in range(100):  # max iterations
        new_values = values.copy()
        for cell, (i, j) in cells.items():
            if cell == goal:
                continue
            max_value = float('-inf')
            best_action = None
            for action in actions:
                ni, nj = i + action[0], j + action[1]
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]) and grid[ni][nj] != 'X':
                    neighbor = grid[ni][nj]
                    value = -1 + values.get(neighbor, float('-inf'))
                    if value > max_value:
                        max_value = value
                        best_action = action
            new_values[cell] = max_value
            policy[cell] = best_action
        values = new_values

    # Cluster the states based on their optimal actions and expected values
    clusters = defaultdict(list)
    for cell, (i, j) in cells.items():
        if cell == goal:
            cluster_key = 'goal'
        else:
            cluster_key = (policy[cell], round(values[cell], 2))
        clusters[cluster_key].append(cell)

    return dict(clusters)


